Object.assign(window.CATALOG_I18N["anker-solix-s2000-3000w-pico-1500w-nominal-2010wh-swri4"]=window.CATALOG_I18N["anker-solix-s2000-3000w-pico-1500w-nominal-2010wh-swri4"]||{},{d:{en:"MODEL:\nANKER SOLIX S2000\n\nCAPACITY:\n2010Wh\n\nAC OUTPUT:\n1500 W\n\nMAX POWER:\n3000 W (PEAK)\n\nBATTERY TYPE:\nLiFePO₄\n\nCELLS:\n314 Ah LFP\n\nSERVICE LIFE:\n6,000 cycles at 80% / 10,000 cycles at 60%\n\nBYPASS POWER:\nUp to 1800 W\n\nULTRA-FAST AC INPUT:\nUp to 1600 W\n\nMPPT SOLAR INPUT:\nUp to 400 W\n\nUPS:\n≤10 ms\n\nUSB-C:\n100 W + 15 W\n\nUSB-A:\n12 W\n\nNUMBER OF AC OUTLETS:\n3 front - 2 rear\n\nSOLAR CONNECTOR:\nXT60i",ar:"الطراز:\nANKER SOLIX S2000\n\nالسعة:\n2010 واط·ساعة\n\nخرج التيار المتردد:\n1500 واط\n\nأقصى قدرة:\n3000 واط (ذروة)\n\nنوع البطارية:\nLiFePO₄\n\nالخلايا:\n314 أمبير·ساعة LFP\n\nالعمر التشغيلي:\n6000 دورة عند 80% / 10000 دورة عند 60%\n\nقدرة التمرير (Bypass):\nحتى 1800 واط\n\nدخل التيار المتردد فائق السرعة:\nحتى 1600 واط\n\nدخل شمسي MPPT:\nحتى 400 واط\n\nمزوّد الطاقة غير المنقطعة:\n‏≤10 ميلي ثانية\n\nمنفذ USB-C:\n‏100 واط + 15 واط\n\nمنفذ USB-A:\n‏12 واط\n\nعدد مخارج التيار المتردد:\n3 أمامية - 2 خلفية\n\nموصّل الطاقة الشمسية:\nXT60i"}});
